import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"UI 可视化编辑器","description":"灵萌 UI 编辑器使用指南：39 种组件拖拽搭建首页、TabBar 与业务页面，按区域保存，无需发版即可调整客户端界面。","frontmatter":{"title":"UI 可视化编辑器","description":"灵萌 UI 编辑器使用指南：39 种组件拖拽搭建首页、TabBar 与业务页面，按区域保存，无需发版即可调整客户端界面。"},"headers":[],"relativePath":"features/ui-editor/index.md","filePath":"features/ui-editor/index.md","lastUpdated":1785018026000}'),s={name:"features/ui-editor/index.md"};function d(o,t,n,l,h,u){return e(),r("div",null,[...t[0]||(t[0]=[i(`<p>灵萌的 <strong>UI 可视化编辑器</strong> 是系统核心特色之一：无需改代码，在管理后台拖拽组件、调整样式与跳转，即可为不同区域定制客户端界面。</p><div class="tip custom-block"><p class="custom-block-title">使用环境</p><p>UI 编辑器 <strong>仅支持 H5 浏览器</strong>（电脑 Chrome / Edge 体验最佳）。请勿在小程序内打开管理后台。</p></div><h2 id="入口位置" tabindex="-1">入口位置 <a class="header-anchor" href="#入口位置" aria-label="Permalink to &quot;入口位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>菜单路径</th></tr></thead><tbody><tr><td>页面列表与可视化设计</td><td><strong>UI管理 → 页面配置</strong></td></tr><tr><td>底部 Tab 导航</td><td><strong>UI管理 → TabBar配置</strong></td></tr><tr><td>笔记标签样式</td><td><strong>UI管理 → 自定义标签</strong></td></tr></tbody></table><p>前置条件：侧栏出现 <strong>UI管理</strong>（需在 <strong>系统设置 → 我的模块</strong> 中已开通 UI 配置能力）。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li>为 <strong>首页、发现页、自定义页、圈子页、跑腿表单页</strong> 等拖拽搭建界面</li><li>配置 <strong>个人中心、消息中心、设置页</strong> 等面板类页面</li><li>按 <strong>区域</strong> 分别保存 UI（多校区/多社区各自一套）</li><li>配置底部 <strong>TabBar</strong> 图标、文案、跳转与发布弹窗</li><li>使用 <strong>AI 助手</strong> 根据描述生成页面布局（可选）</li></ul><h2 id="编辑器三栏布局" tabindex="-1">编辑器三栏布局 <a class="header-anchor" href="#编辑器三栏布局" aria-label="Permalink to &quot;编辑器三栏布局&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬─────────────────────────┬──────────────┐</span></span>
<span class="line"><span>│  左侧组件库   │   中间手机预览画布        │  右侧属性面板 │</span></span>
<span class="line"><span>│  点击添加组件 │   点击选中 / 排序 / 删除  │  属性 + 样式  │</span></span>
<span class="line"><span>└──────────────┴─────────────────────────┴──────────────┘</span></span></code></pre></div><p>宽屏电脑为三栏；手机管理端底部切换 <strong>组件 / 画布 / AI / 属性</strong> 四个 Tab。</p><h2 id="组件库概览-39-种" tabindex="-1">组件库概览（39 种） <a class="header-anchor" href="#组件库概览-39-种" aria-label="Permalink to &quot;组件库概览（39 种）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>数量</th><th>典型组件</th></tr></thead><tbody><tr><td><a href="/features/ui-editor/components-basic">基础元素</a></td><td>4</td><td>文本、图片、按钮、模块标题</td></tr><tr><td><a href="/features/ui-editor/components-layout">布局导航</a></td><td>5</td><td>轮播图、金刚区、搜索栏、筛选标签</td></tr><tr><td><a href="/features/ui-editor/components-display">信息展示</a></td><td>3</td><td>列表、通知栏、结束文本</td></tr><tr><td><a href="/features/ui-editor/components-community">社区内容</a></td><td>8</td><td>笔记列表、瀑布流、圈子列表、热门话题</td></tr><tr><td><a href="/features/ui-editor/components-marketing">运营模块</a></td><td>3</td><td>首页榜单、双卡行动、小程序广告</td></tr><tr><td><a href="/features/ui-editor/components-form">表单/服务</a></td><td>16</td><td>输入框、选项、地址、提交底栏（仅服务表单页）</td></tr></tbody></table><h2 id="配置的两层逻辑" tabindex="-1">配置的两层逻辑 <a class="header-anchor" href="#配置的两层逻辑" aria-label="Permalink to &quot;配置的两层逻辑&quot;">​</a></h2><p>与全站其它功能一致：</p><table tabindex="0"><thead><tr><th>层级</th><th>说明</th></tr></thead><tbody><tr><td><strong>平台默认</strong>（区域 ID = 0）</td><td>各区域未单独配置时继承</td></tr><tr><td><strong>区域专属</strong></td><td>在页面列表顶部选择区域后编辑保存</td></tr></tbody></table><p>同一页面类型、同一区域 <strong>只能有一条「启用」</strong> 的配置对用户生效。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li><a href="/features/ui-editor/getting-started">快速上手</a> — 创建、编辑、保存、启用</li><li><strong><a href="/features/ui-editor/scenarios/homepage">从零搭建首页</a></strong> — 完整案例（推荐）</li><li><a href="/features/ui-editor/interface">编辑器界面说明</a> — 工具栏、撤销、导入导出</li><li><a href="/features/ui-editor/page-types">页面类型说明</a> — 首页/面板/表单页区别</li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a> — 通用样式面板、跳转配置</li><li>按需查阅 <a href="/features/ui-editor/components-basic">组件手册</a></li><li><a href="/features/ui-editor/tabbar">TabBar 配置</a></li><li><a href="/features/ui-editor/ai-panel">AI 生成页面</a>（可选）</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/region">区域管理</a></li><li><a href="/features/circle-note">圈子与笔记</a></li><li><a href="/features/errand">跑腿</a></li><li><a href="/features/ui-editor/faq">常见问题</a></li></ul>`,20)])])}const f=a(s,[["render",d]]);export{c as __pageData,f as default};
